<?php use App\Core\Authorization;use App\Core\Csrf; ?>
<div class="page-heading"><div><p class="eyebrow">Operations</p><h1>Database backups</h1><p>Create recoverable local SQL snapshots before major changes.</p></div><?php if(Authorization::allows('backups.create')):?><form method="post" action="<?=e(url('/admin/backups'))?>"><?=Csrf::field()?><button class="button primary">Create backup</button></form><?php endif;?></div><div class="alert danger"><strong>Restore caution:</strong> restoring replaces current database records with the selected snapshot. Create a fresh backup first.</div><section class="card table-card"><table><thead><tr><th>File</th><th>Created</th><th>Size</th><th>Status</th><th>Checksum</th><th>Actions</th></tr></thead><tbody><?php foreach($backups as $b):?><tr><td><strong><?=e($b['file_name'])?></strong><br><small><?=e($b['creator'])?></small></td><td><?=e($b['created_at'])?></td><td><?=number_format(((int)$b['file_size'])/1024,1)?> KB</td><td><span class="badge"><?=e($b['status'])?></span></td><td><code><?=e(substr((string)$b['checksum_sha256'],0,12))?>…</code></td><td><a class="button small" href="<?=e(url('/admin/backups/'.$b['id'].'/download'))?>">Download</a><?php if(Authorization::allows('backups.restore')):?><details class="restore-box"><summary>Restore</summary><form method="post" action="<?=e(url('/admin/backups/'.$b['id'].'/restore'))?>"><?=Csrf::field()?><label>Type RESTORE<input required name="confirm_text" autocomplete="off"></label><label>Current password<input required type="password" name="current_password" autocomplete="current-password"></label><button class="button danger-button">Restore snapshot</button></form></details><?php endif;?></td></tr><?php endforeach;?><?php if(!$backups):?><tr><td colspan="6" class="empty">No database backups created yet.</td></tr><?php endif;?></tbody></table></section>
